from src.nodes.base import BaseNode
from src.runtime.assets.acquisition_online import get_asset_cache_manager

class Hou_Mcp_Asset_Cache(BaseNode):
    name = "hou_mcp_asset_cache"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("action",     "string", widget_type="text", default="stats")
        self.add_input("asset_id",   "string", widget_type="text")
        self.add_input("provider",   "string", widget_type="text", default="megascans")
        self.add_input("local_path", "string", widget_type="text")
        self.add_input("checksum",   "string", widget_type="text")
        self.add_input("version",    "string", widget_type="text")
        self.add_output("local_path", "string")
        self.add_output("exists",     "bool")
        self.add_output("entry",      "any")
        self.add_output("entries",    "list")
        self.add_output("stats",      "any")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        action   = str(inputs.get("action") or "stats").strip().lower()
        asset_id = str(inputs.get("asset_id") or "").strip()
        provider = str(inputs.get("provider") or "megascans").strip()
        lpath    = str(inputs.get("local_path") or "").strip()
        checksum = str(inputs.get("checksum") or "").strip()
        version  = str(inputs.get("version") or "").strip()
        try:
            cache = get_asset_cache_manager()
            if action == "exists":
                ex = cache.asset_exists(asset_id, provider)
                return {"local_path": "", "exists": ex, "entry": {}, "entries": [], "stats": {}, "exec_out": True}
            elif action == "get_path":
                p = cache.get_asset_path(asset_id, provider) or ""
                return {"local_path": p, "exists": bool(p), "entry": {}, "entries": [], "stats": {}, "exec_out": True}
            elif action == "cache":
                entry = cache.cache_asset(asset_id, provider, lpath, version=version, checksum=checksum)
                return {"local_path": entry.local_path, "exists": True, "entry": entry.to_dict(), "entries": [], "stats": {}, "exec_out": True}
            elif action == "remove":
                ok = cache.remove_asset(asset_id, provider)
                return {"local_path": "", "exists": False, "entry": {"removed": ok}, "entries": [], "stats": {}, "exec_out": True}
            elif action == "list":
                entries = [e.to_dict() for e in cache.list_cached_assets()]
                return {"local_path": "", "exists": False, "entry": {}, "entries": entries, "stats": cache.cache_statistics(), "exec_out": True}
            else:
                return {"local_path": "", "exists": False, "entry": {}, "entries": [], "stats": cache.cache_statistics(), "exec_out": True}
        except Exception as e:
            self.log_error(f"hou_mcp_asset_cache failed: {e}")
            return {"local_path": "", "exists": False, "entry": {}, "entries": [], "stats": {}, "exec_out": True}

def register_node():
    return Hou_Mcp_Asset_Cache
